insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_78_v1'
from (values
('127.600.d.1.A',3,'Help-wanted ads, online job boards, and a school career center are all ways to identify:','["employment opportunities", "tax deductions", "school holidays", "menu items"]'::jsonb,0,'Job seekers look in many places to find openings.','original'),
('127.600.d.1.A',4,'A cook who learns about openings through a classmate''s cousin who works at a bakery is using a personal:','["receipt", "network", "uniform", "recipe"]'::jsonb,1,'Personal contacts are a common way to hear about jobs.','original'),
('127.600.d.1.B',3,'Arriving early to an interview and speaking clearly are essential workplace skills used when you are:','["ordering supplies", "cleaning a grill", "applying for a job", "paying a bill"]'::jsonb,2,'Workplace skills help you make a strong impression during the hiring process.','original'),
('127.600.d.1.B',4,'Bringing a pen, a copy of your resume, and a list of references to an interview shows that you are:','["nervous", "late", "careless", "prepared"]'::jsonb,3,'Preparation shows employers you take the job seriously.','original'),
('127.600.d.1.C',3,'Which form proves a new hire is legally allowed to work in the United States?','["Form I-9", "a library card", "a menu", "Form W-4"]'::jsonb,0,'The I-9 verifies identity and employment eligibility.','original'),
('127.600.d.1.C',4,'Which form tells a new employer how much income tax to withhold from your paychecks?','["a food permit", "Form W-4", "Form I-9", "a time card"]'::jsonb,1,'The W-4 guides federal tax withholding.','original'),
('127.600.d.1.D',3,'When an interviewer asks about your greatest weakness, a strong answer names a real weakness and explains how you are:','["denying it", "blaming others", "improving it", "hiding it"]'::jsonb,2,'Honesty plus growth shows maturity.','original'),
('127.600.d.1.D',4,'Asking the interviewer a thoughtful question about the kitchen team at the end of an interview shows:','["impatience", "poor manners", "confusion", "genuine interest"]'::jsonb,3,'Good questions show you care about the job.','original'),
('127.600.d.2.A',3,'In a commercial kitchen, which is part of proper grooming?','["wearing a hair restraint", "keeping long nails", "wearing strong perfume", "wearing rings and bracelets"]'::jsonb,0,'Hair restraints keep hair out of food; jewelry and long nails are hygiene risks.','original'),
('127.600.d.2.A',4,'Wearing a clean uniform and closed-toe, non-slip shoes in the kitchen supports both a professional look and:','["gossip", "safety", "tardiness", "costs"]'::jsonb,1,'Proper attire protects workers from slips and burns.','original'),
('127.600.d.2.B',3,'A line cook who calls ahead when running late and still arrives prepared shows:','["carelessness", "laziness", "dependability", "impatience"]'::jsonb,2,'Dependable workers communicate and follow through.','original'),
('127.600.d.2.B',4,'A prep cook who notices low stock of onions and tells the chef before the lunch rush is showing:','["indifference", "stubbornness", "hesitation", "initiative"]'::jsonb,3,'Initiative means acting without being told.','original'),
('127.600.d.2.C',3,'A kitchen team includes workers from many cultures. A respectful coworker will:','["learn about and value their differences", "make jokes about accents", "assign them the hardest tasks", "avoid talking to them"]'::jsonb,0,'Respect for diversity builds a strong team.','original'),
('127.600.d.2.C',4,'Using polite, inclusive language with all coworkers helps build positive:','["deadlines", "relationships", "menus", "invoices"]'::jsonb,1,'Courtesy creates trust.','original'),
('127.600.d.2.D',3,'In a restaurant kitchen, saying ''behind'' or ''corner'' when walking behind a coworker is an example of workplace:','["rivalry", "delay", "courtesy", "gossip"]'::jsonb,2,'These calls prevent collisions and show consideration.','original'),
('127.600.d.2.D',4,'Using your phone for personal texts while on the line during service breaks workplace:','["inventory", "payroll", "tradition", "etiquette"]'::jsonb,3,'Focus is expected during service.','original'),
('127.600.d.2.E',3,'A baker who weighs every ingredient accurately even when no one is checking shows good work habits and:','["ethics", "rivalry", "fashion", "delay"]'::jsonb,0,'Doing the job right when unobserved reflects integrity.','original'),
('127.600.d.2.E',4,'Staying cheerful and focused during a stressful dinner rush reflects a positive:','["mascot", "attitude", "invoice", "recipe"]'::jsonb,1,'A good attitude helps the whole team.','original'),
('127.600.d.2.F',3,'Washing hands after handling raw poultry protects the health and safety of both the cook and the:','["inspectors", "suppliers", "customers", "landlords"]'::jsonb,2,'Hand washing prevents spreading bacteria to food and guests.','original'),
('127.600.d.2.F',4,'Lifting heavy stockpots with your legs, not your back, helps prevent:','["profit", "hunger", "praise", "injury"]'::jsonb,3,'Proper lifting protects the back.','original'),
('127.600.d.2.G',3,'When the dishwasher calls out sick, a cook who offers to help clean up is working with others to support the:','["organization", "competition", "vendors", "inspectors"]'::jsonb,0,'Helping coworkers keeps the operation running.','original'),
('127.600.d.2.G',4,'On a busy night, the grill cook calls out orders and the expo checks plates. This teamwork helps the whole kitchen meet its:','["rumors", "goals", "lunches", "fines"]'::jsonb,1,'Coordinated effort reaches shared objectives.','original'),
('127.600.d.2.H',3,'A cook has stocks to simmer, vegetables to cut, and a special to plan before lunch. The best way to prioritize is to start with the tasks that:','["can be skipped", "are easiest", "take longest or are due first", "are most fun"]'::jsonb,2,'Long or urgent tasks must start first to finish on time.','original'),
('127.600.d.2.H',4,'Setting a timer for a roast and prepping side dishes while it cooks helps a cook meet:','["holidays", "vacations", "nicknames", "deadlines"]'::jsonb,3,'Multitasking with timers keeps food ready on time.','original'),
('127.600.d.2.I',3,'Getting enough sleep and eating balanced meals helps kitchen workers stay focused and avoid:','["mistakes", "promotions", "tips", "breaks"]'::jsonb,0,'Good health improves concentration.','original'),
('127.600.d.2.I',4,'Managing stress through exercise and rest supports both mental health and long-term job:','["failure", "success", "conflict", "absence"]'::jsonb,1,'Healthy habits help workers perform well over time.','original'),
('127.600.d.2.J',3,'A kitchen manager posts the daily specials and prep list on a shared tablet. This is an example of:','["spoken instructions", "a handwritten postcard", "electronic communication", "body language"]'::jsonb,2,'Digital tools share information quickly.','original'),
('127.600.d.2.J',4,'A chef raising a hand to signal ''stop'' across a noisy kitchen is using:','["a recipe card", "written communication", "electronic communication", "non-verbal communication"]'::jsonb,3,'Gestures send messages without words.','original'),
('127.600.d.2.K',3,'A line cook repeats back a rush order, ''2 medium steaks, 1 well done,'' to confirm it. This is a listening skill called:','["paraphrasing", "interrupting", "guessing", "daydreaming"]'::jsonb,0,'Repeating back ensures accuracy.','original'),
('127.600.d.2.K',4,'Looking at the chef and not at your phone while receiving instructions shows:','["fatigue", "attentiveness", "anger", "boredom"]'::jsonb,1,'Giving full attention is part of listening well.','original'),
('127.600.d.3.A',3,'A cook who admits spilling a sauce and offers to remake it earns coworkers'' trust because of personal:','["luck", "rank", "integrity", "speed"]'::jsonb,2,'Honesty and accountability build trust.','original'),
('127.600.d.3.A',4,'Coworkers are more willing to cooperate with someone who keeps promises, which shows how integrity improves:','["menu fonts", "food costs", "kitchen layouts", "human relations"]'::jsonb,3,'Trustworthy people have better working relationships.','original'),
('127.600.d.3.B',3,'Sharing the workload, communicating clearly, and trusting each other are characteristics of successful:','["teamwork", "rivalry", "isolation", "competition"]'::jsonb,0,'Teamwork depends on cooperation and trust.','original'),
('127.600.d.3.B',4,'A good working relationship depends on mutual trust, open communication, and:','["blame", "respect", "favoritism", "secrecy"]'::jsonb,1,'Respect is the foundation of cooperation.','original'),
('127.600.d.3.C',3,'Following the recipe card, plating guide, and portion sizes set by the restaurant is meeting its:','["personal preferences", "local traditions", "employer expectations", "customer complaints"]'::jsonb,2,'Employees are expected to follow the standards set by the employer.','original'),
('127.600.d.3.C',4,'When a manager asks all cooks to label and date stored foods, the cooks should:','["do it only when watched", "ignore it when busy", "let others do it", "do it every time"]'::jsonb,3,'Consistency is part of meeting expectations.','original'),
('127.600.d.3.D',3,'Respecting a coworker''s right to privacy means you do not:','["share their personal information", "say thank you", "work beside them", "greet them"]'::jsonb,0,'Personal information should stay private.','original'),
('127.600.d.3.D',4,'A cook who does not touch a coworker''s belongings or lunch is showing respect for others'':','["schedule", "property", "title", "salary"]'::jsonb,1,'Respecting rights includes respecting what belongs to others.','original'),
('127.600.d.3.E',3,'Reporting a food safety violation even when a friend caused it follows ethical:','["traditions", "favors", "standards", "rumors"]'::jsonb,2,'Ethical standards put safety and honesty first.','original'),
('127.600.d.3.E',4,'Padding a time card with hours you did not work is:','["traditional", "efficient", "generous", "dishonest"]'::jsonb,3,'Falsifying time records is unethical and may be illegal.','original'),
('127.600.d.3.F',3,'A restaurant policy that all employees clock in before starting work means:','["everyone must clock in", "only managers clock in", "clock in after finishing", "clocking in is optional"]'::jsonb,0,'Policies apply to all employees.','original'),
('127.600.d.3.F',4,'Violating a written company policy, such as the dress code, can lead to a:','["vacation", "disciplinary action", "free meal", "raise"]'::jsonb,1,'Policies are enforced with consequences.','original'),
('127.600.d.4.A',3,'A bakery sells 12 muffins at $2.50 each. What is the total before tax?','["$25.00", "$14.50", "$30.00", "$24.50"]'::jsonb,2,'12 x 2.50 = 30.00.','original'),
('127.600.d.4.A',4,'A customer''s bill is $40 and they leave a 15% tip. What is the tip amount?','["$55.00", "$4.00", "$15.00", "$6.00"]'::jsonb,3,'0.15 x 40 = 6.','original'),
('127.600.d.4.B',3,'A new line cook earns $2,400 per month in take-home pay and spends $1,100 on rent. How much remains for other expenses and savings?','["$1,300", "$1,000", "$3,500", "$1,100"]'::jsonb,0,'2,400 - 1,100 = 1,300.','original'),
('127.600.d.4.B',4,'When planning a budget for a culinary career, the first step is to estimate your monthly:','["tips only", "income", "hobbies", "weather"]'::jsonb,1,'A budget starts with knowing how much money comes in.','original'),
('127.600.d.4.C',3,'A bar graph shows sales of five menu items. The tallest bar represents the item with the:','["fewest orders", "oldest recipe", "highest sales", "lowest price"]'::jsonb,2,'Taller bars show larger values.','original'),
('127.600.d.4.C',4,'A chart shows that dessert sales rise every Friday and Saturday. A manager can use this to estimate:','["employee ages", "paint colors", "last year''s rent", "future demand"]'::jsonb,3,'Trends help predict what will sell.','original'),
('127.600.d.4.D',3,'A manager writes a clear, error-free memo announcing a new prep schedule. This shows skill at composing workplace:','["documents", "uniforms", "recipes", "rumors"]'::jsonb,0,'Clear writing is part of workplace communication.','original'),
('127.600.d.4.D',4,'Before sending a workplace email, you should proofread it for spelling, grammar, and:','["length of title", "tone", "font color only", "emoji count"]'::jsonb,1,'Tone affects how the message is received.','original'),
('127.600.d.5.A',3,'A fast-food restaurant and a fine-dining restaurant may have different dress code policies. Comparing them shows that workplace policies:','["are illegal", "do not matter", "vary by establishment", "are identical everywhere"]'::jsonb,2,'Each business sets rules that fit its style and needs.','original'),
('127.600.d.5.A',4,'Before accepting a job offer, an applicant should read the employee handbook to understand the employer''s written:','["menus", "jokes", "recipes", "policies"]'::jsonb,3,'The handbook explains expectations and rules.','original'),
('127.600.d.5.B',3,'A server notices a customer left a wallet on a table. The responsible and ethical action is to:','["turn it in to a manager", "keep the cash", "ignore it", "post a joke about it"]'::jsonb,0,'Returning lost property is honest and responsible.','original'),
('127.600.d.5.B',4,'Taking credit for a coworker''s idea is an example of:','["responsible behavior", "unethical behavior", "good teamwork", "professional courtesy"]'::jsonb,1,'Giving credit where it is due is part of ethics.','original'),
('127.600.d.5.C',3,'The Fair Labor Standards Act sets federal rules for minimum wage, overtime pay, and:','["food safety", "menu pricing", "child labor", "parking"]'::jsonb,2,'The FLSA also limits the work minors may do.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_78_v1'
from (values
('127.600.d.5.C',4,'Under the FLSA, most non-exempt workers must be paid overtime for hours worked over:','["20 in a workweek", "8 in a month", "60 in a workweek", "40 in a workweek"]'::jsonb,3,'Overtime is generally 1.5 times pay after 40 hours in a week.','original'),
('127.600.d.5.D',3,'A chef shares a restaurant''s secret sauce recipe with a competitor. This breach of confidentiality could result in:','["termination or legal action", "a vacation", "a promotion", "a bonus"]'::jsonb,0,'Revealing trade secrets can cost a worker the job and lead to lawsuits.','original'),
('127.600.d.5.D',4,'Customer information such as credit card numbers must be kept:','["shared online", "confidential", "public", "posted"]'::jsonb,1,'Protecting customer data prevents fraud and loss of trust.','original'),
('127.600.d.5.E',3,'A law requiring a restaurant to pass periodic health inspections is intended to protect:','["chef salaries", "restaurant profits", "public health", "menu prices"]'::jsonb,2,'Inspections help prevent foodborne illness.','original'),
('127.600.d.5.E',4,'Serving alcohol to a minor is illegal, so servers who serve alcohol must check customers'':','["shoe sizes", "appetites", "coupons", "identification"]'::jsonb,3,'Checking ID verifies legal age.','original'),
('127.600.d.6.A',3,'A kitchen team-building activity, such as planning a menu together, helps coworkers practice:','["cooperation", "blame", "rivalry", "isolation"]'::jsonb,0,'Working toward a shared goal builds cooperation.','original'),
('127.600.d.6.A',4,'When a teammate makes a mistake, a good team member offers help instead of:','["thanking", "blaming", "teaching", "coaching"]'::jsonb,1,'Supportive teammates solve problems together.','original'),
('127.600.d.6.B',3,'Competing in a culinary skills contest through a career and technical student organization helps students build leadership and:','["rivalries", "grudges", "career skills", "debts"]'::jsonb,2,'Student organizations develop skills for the workplace.','original'),
('127.600.d.6.B',4,'Serving as an officer in a student organization gives students practice in running meetings and:','["hiding mistakes", "avoiding work", "skipping class", "leading others"]'::jsonb,3,'Officer roles teach leadership.','original'),
('127.600.d.7.A',3,'Which is a safe working practice when using a chef''s knife?','["cutting away from your body on a stable board", "catching a falling knife", "cutting while distracted", "carrying it with the blade up"]'::jsonb,0,'Stable boards and cutting away from the body reduce injury risk.','original'),
('127.600.d.7.A',4,'Wiping up a spill immediately and placing a wet-floor sign is a safe practice that prevents:','["sales", "slips and falls", "traffic", "tardiness"]'::jsonb,1,'Wet floors are a major cause of kitchen injuries.','original'),
('127.600.d.7.B',3,'A coworker regularly leaves knives in the sink. A good solution is to calmly remind them and suggest a safe:','["joke", "insult", "storage place", "bet"]'::jsonb,2,'Respectful reminders and solutions fix unsafe habits.','original'),
('127.600.d.7.B',4,'An attitude of ''It won''t happen to me'' can lead to unsafe behavior. To address it, a supervisor can use safety:','["bonuses only", "gossip", "gambling", "training"]'::jsonb,3,'Training shows why safety rules matter.','original'),
('127.600.d.7.C',3,'OSHA requires employers to keep exits unlocked and unobstructed so workers can:','["escape in an emergency", "receive deliveries", "take breaks", "hang decorations"]'::jsonb,0,'Clear exits save lives during fires or other emergencies.','original'),
('127.600.d.7.C',4,'Under OSHA rules, workers have the right to report hazards without fear of:','["promotion", "retaliation", "praise", "training"]'::jsonb,1,'Employers cannot punish workers for reporting safety concerns.','original'),
('127.600.d.7.D',3,'Staying hydrated during a hot kitchen shift helps a worker avoid dizziness and maintain:','["gossip", "tardiness", "performance", "debt"]'::jsonb,2,'Good health habits support steady work.','original'),
('127.600.d.7.D',4,'Regular exercise, rest, and stress management are wellness practices that can improve:','["menu prices", "uniform sizes", "parking", "job performance"]'::jsonb,3,'Healthy workers are more productive.','original'),
('127.600.d.7.E',3,'A state or national food handler certification shows that a worker has learned safe food:','["handling practices", "pricing methods", "marketing plans", "decorating styles"]'::jsonb,0,'Certification proves knowledge of food safety.','original'),
('127.600.d.7.E',4,'Studying temperature danger zones and cross-contamination helps students prepare for a food:','["cooking contest", "sanitation exam", "cash register test", "driving test"]'::jsonb,1,'These topics are on food safety certification exams.','original'),
('127.600.d.8.A',3,'A report showing that demand for cooks and chefs is expected to grow describes the occupation''s job:','["penalty", "receipt", "outlook", "uniform"]'::jsonb,2,'Employment outlook predicts future job opportunities.','original'),
('127.600.d.8.A',4,'Reading the Occupational Outlook Handbook helps a student learn about expected job growth and:','["parking rules", "lunch menus", "uniform colors", "typical pay"]'::jsonb,3,'The handbook lists wages, training, and growth projections.','original'),
('127.600.d.8.B',3,'Opening a catering company, food truck, or bakery are examples of entrepreneurial opportunities in:','["culinary arts", "aviation", "banking", "mining"]'::jsonb,0,'Many cooks become business owners.','original'),
('127.600.d.8.B',4,'Before starting a food truck, an entrepreneur should research local permits, startup costs, and:','["moon phases", "target customers", "school mascots", "bus schedules"]'::jsonb,1,'Good planning studies rules, money, and the market.','original'),
('127.600.d.8.C',3,'A professional who arranges food so it looks appealing in photos and advertisements is a food:','["inspector", "auditor", "stylist", "importer"]'::jsonb,2,'Food stylists make dishes look their best on camera.','original'),
('127.600.d.8.C',4,'Writing about restaurants and recipes for magazines and websites is a nontraditional career called food:','["auditor", "cashier", "importer", "writer"]'::jsonb,3,'Food writers combine cooking knowledge with writing skills.','original'),
('127.600.d.8.D',3,'When researching a career as a pastry chef, you should look at salary, required skills, and:','["education and training", "favorite colors", "bus routes", "lunch breaks"]'::jsonb,0,'A career path includes pay, skills, and preparation needed.','original'),
('127.600.d.8.D',4,'Starting as a line cook, moving to sous chef, and then executive chef shows a career:','["tax", "path", "fine", "error"]'::jsonb,1,'A career path is the series of steps toward a goal.','original'),
('127.600.d.8.E',3,'Learning new cuisines and kitchen technology helps a chef stay employable as the industry:','["stays still", "ends", "changes", "shrinks"]'::jsonb,2,'Continual learning keeps skills current.','original'),
('127.600.d.8.E',4,'Earning an advanced certification can help a cook qualify for a:','["suspension", "vacation", "demotion", "promotion"]'::jsonb,3,'Added credentials support advancement.','original'),
('127.600.d.8.F',3,'An employer''s responsibility includes providing a safe workplace, while an employee''s responsibility includes:','["following safety rules", "setting wages", "hiring managers", "ignoring the schedule"]'::jsonb,0,'Both sides share duties.','original'),
('127.600.d.8.F',4,'Employees have the right to be paid for hours worked and the responsibility to:','["choose their own pay", "perform assigned duties", "skip shifts", "leave early"]'::jsonb,1,'Workers earn pay by doing the job they agreed to do.','original'),
('127.600.d.8.G',3,'Setting aside part of each paycheck for emergencies is part of financial:','["gambling", "debt", "planning", "spending"]'::jsonb,2,'An emergency fund protects against unexpected costs.','original'),
('127.600.d.8.G',4,'Paying credit card balances in full each month helps a person avoid paying extra:','["tips", "rent", "wages", "interest"]'::jsonb,3,'Unpaid balances accumulate interest charges.','original'),
('127.600.d.9.A',3,'Two job offers pay the same, but one includes health insurance and paid vacation. The second offer has fewer:','["benefits", "uniforms", "hours", "customers"]'::jsonb,0,'Total compensation includes benefits, not just salary.','original'),
('127.600.d.9.A',4,'A salary is the pay for the job, while benefits include insurance, vacation, and:','["dress codes", "retirement plans", "sick customers", "parking tickets"]'::jsonb,1,'Benefits add value beyond pay.','original'),
('127.600.d.9.B',3,'Personal interests, abilities, and values are factors that affect a person''s:','["height", "birthday", "career choices", "eye color"]'::jsonb,2,'People choose careers that fit who they are.','original'),
('127.600.d.9.B',4,'A person who loves creating new dishes and working with teams might choose a career in:','["surveying", "accounting", "pharmacy", "culinary arts"]'::jsonb,3,'Interests help guide career decisions.','original'),
('127.600.d.9.C',3,'Taking a night class in advanced pastry techniques is an example of continuing:','["education", "rivalry", "debt", "vacation"]'::jsonb,0,'Continuing education builds skills after you start working.','original'),
('127.600.d.9.C',4,'Continuing education can help a worker earn a higher position and keep skills:','["small", "up to date", "secret", "hidden"]'::jsonb,1,'Ongoing learning keeps workers competitive.','original'),
('127.600.d.9.D',3,'When leaving a job, the professional way to resign is to give written notice at least:','["a month after leaving", "never", "two weeks in advance", "one hour after leaving"]'::jsonb,2,'Two weeks'' notice is the customary courtesy.','original'),
('127.600.d.9.D',4,'To maintain employment, a worker should arrive on time, follow policies, and:','["argue with customers", "skip training", "ignore feedback", "do quality work"]'::jsonb,3,'Reliable, quality work helps keep a job.','original'),
('127.600.d.10.A',3,'A commercial mixer used for large batches of dough is an example of large:','["equipment", "ingredients", "utensils", "garnishes"]'::jsonb,0,'Large equipment handles volume production.','original'),
('127.600.d.10.A',4,'A paring knife, whisk, and peeler are examples of small kitchen:','["walk-ins", "tools", "hoods", "ovens"]'::jsonb,1,'Small tools are used for hands-on prep.','original'),
('127.600.d.10.B',3,'Placing the protein at the front of the plate, the starch to one side, and a vegetable for color is a basic plating technique for good:','["ordering", "storage", "presentation", "receiving"]'::jsonb,2,'Balanced plating makes dishes look appealing.','original'),
('127.600.d.10.B',4,'Cutting vegetables into uniform sizes helps them cook evenly and look more:','["frozen", "bitter", "expensive", "appealing"]'::jsonb,3,'Consistent cuts improve cooking and appearance.','original'),
('127.600.d.10.C',3,'Braising meat by browning it and then simmering in liquid is a:','["combination cooking method", "cold smoking method", "dry heat method", "raw preparation"]'::jsonb,0,'Braising uses both dry and moist heat.','original'),
('127.600.d.10.C',4,'Which is a moist-heat cooking method?','["broiling", "steaming", "roasting", "grilling"]'::jsonb,1,'Steaming cooks food with hot vapor.','original'),
('127.600.d.10.D',3,'Setting up all chopped ingredients, sauces, and tools before service begins is called:','["receiving", "garnishing", "mise en place", "plating"]'::jsonb,2,'Mise en place means everything in its place.','original'),
('127.600.d.10.D',4,'In commercial kitchens, preparing a large batch of stock instead of a single serving is called:','["flash freezing", "a la carte plating", "tempering eggs", "batch cooking"]'::jsonb,3,'Batch cooking prepares large quantities for service.','original'),
('127.600.d.10.E',3,'Yeast breads rise because yeast produces carbon dioxide as it ferments the dough''s:','["sugars", "proteins", "salts", "oils"]'::jsonb,0,'Yeast feeds on sugars and releases gas.','original'),
('127.600.d.10.E',4,'Quick breads such as muffins and banana bread rise using baking soda or baking powder instead of:','["flour", "yeast", "water", "eggs"]'::jsonb,1,'Chemical leaveners work faster than yeast.','original'),
('127.600.d.10.F',3,'When receiving a delivery of fresh chicken, a cook should check that its temperature is at or below:','["60°F", "70°F", "41°F", "85°F"]'::jsonb,2,'Poultry must be received at 41°F or lower.','original'),
